  if (!owned(fb)) return -EPERM;
  ret = k7vop_validate_frame(&fb->frame);
  if (ret != 0) return ret;
  ret = fb->io.verify_mapping(fb->io.arg, K7FB_BASE, K7FB_RESERVED_BYTES);
  return ret > 0 ? -EIO : ret;
}

int k7fb_publish(void *arg, const struct k7vop_frame *frame)
{
