  ret = fb->io.clean_to_poc(fb->io.arg, start, start + frame->bytes);
  if (ret != 0) return ret < 0 ? ret : -EIO;
  ret = fb->io.barrier(fb->io.arg);
  if (ret != 0) return ret < 0 ? ret : -EIO;
