  k7_yunet_destroy(p->yunet);
#endif
#ifdef CONFIG_EXAMPLES_K7HOST_TRACK
  k7_photo_destroy(p->photo);
  gimbal_link_close(p->gimbal_fd);
#endif
  free(p->sink_storage);
  free(p->storage);
  free(p);
  return 0;
}

