  if(strstr(normalized,"不要") || strstr(normalized,"别启动") || strstr(normalized,"取消启动"))return K7_VOICE_NONE;
  /* Explicit wake phrases only. Keep the existing OpenVlea transcription
   * alias, not arbitrary greetings or sentences beginning with "hello". */
  if(!strcmp(normalized,"你好openvela") ||
